/// 初始化 tracing 日志系统
fn init_logging(level: LogLevel, format: LogFormat) {
    let env_filter = EnvFilter::new(level.to_string());

    let use_ansi = format == LogFormat::Text && stderr().is_terminal();

    let subscriber = tracing_subscriber::fmt()
        .with_env_filter(env_filter)
        .with_writer(stderr)
        .with_ansi(use_ansi);

    match format {
        LogFormat::Json => subscriber.json().init(),
        _ => subscriber.init(),
    }
}

/// 运行 WebSocket 服务器, 将 WebSocket 适配为字节流后直接交给 LSP 服务。
async fn run_websocket_server(
    port: u16,
    service: LspService<Backend>,
    socket: ClientSocket,
) -> Result<()> {
    let listener = TcpListener::bind(("127.0.0.1", port)).await?;
    info!("WebSocket server listening on ws://127.0.0.1:{port}");

    // 只接受第一个客户端连接 (LSP 通常单客户端)
    let (stream, addr) = listener.accept().await?;
    info!("Accepted connection from {addr}");

    // 将 WebSocket 包装为字节流
    let ws_stream = WsStream::new(accept_async(stream.compat()).await?);
    let (reader, writer) = tokio::io::split(ws_stream);

    Server::new(reader, writer, socket).serve(service).await;
    Ok(())
}
